// Extract phone and message from Green API payload
const body = $input.item.json;

// Green API webhook format:
// {
//   "typeWebhook": "incomingMessageReceived",
//   "instanceData": { "idInstance": "..." },
//   "timestamp": 1234567890,
//   "body": {
//     "idMessage": "...",
//     "senderData": { "chatId": "85212345678@c.us" },
//     "messageData": { "textMessageData": { "textMessage": "Hello" } }
//   }
// }

let phone = '';
let message = '';
let messageId = '';

if (body.body) {
  const msgData = body.body;
  messageId = msgData.idMessage || '';

  if (msgData.senderData && msgData.senderData.chatId) {
    // Remove @c.us or @g.us suffix
    phone = msgData.senderData.chatId.replace('@c.us', '').replace('@g.us', '');
  }

  if (msgData.messageData) {
    // Text message
    if (msgData.messageData.textMessageData) {
      message = msgData.messageData.textMessageData.textMessage || '';
    }
    // Image with caption
    else if (msgData.messageData.extendedTextMessageData) {
      message = '[圖片] ' + (msgData.messageData.extendedTextMessageData.caption || '');
    }
    // Document
    else if (msgData.messageData.documentMessageData) {
      message = '[文件] ' + (msgData.messageData.documentMessageData.fileName || '');
    }
    // Video
    else if (msgData.messageData.videoMessageData) {
      message = '[影片]';
    }
    // Audio/Voice
    else if (msgData.messageData.audioMessageData) {
      message = '[語音訊息]';
    }
    else {
      message = '[不支援的訊息類型]';
    }
  }
}

// Only process incoming messages (not outgoing/acks)
const typeWebhook = body.typeWebhook || '';
if (typeWebhook !== 'incomingMessageReceived') {
  // Skip ack/notifications
  return null;
}

return {
  phone,
  message,
  messageId,
  timestamp: new Date().toISOString()
};

// Build AI request payload
const user = $input.item.json.user;
const message = $input.item.json.message;
const phone = $input.item.json.phone;

const userContext = user ? {
  name: user.whatsapp_name || '會員',
  rank: user.rank || 'pioneer',
  amway_id: user.amway_id || '未綁定'
} : {
  name: '新會員',
  rank: 'pioneer',
  amway_id: '未綁定'
};

const systemPrompt = `你係 AI 智能大管家，專門為 Amway 直銷商提供服務。

用戶資料：
- 名字: ${userContext.name}
- 職級: ${userContext.rank}
- Amway ID: ${userContext.amway_id}

權限範圍：
${userContext.rank === 'founders' ? '- 全部權限（包括團隊數據）' : ''}
${userContext.rank === 'platinum' || userContext.rank === 'founders' ? '- 獎金計算' : ''}
- 產品查詢
- 訂單管理

重要規則：
1. 只能用廣東話回覆（除非用戶要求英文）
2. 產品價格同 PV 要精確
3. 獎金計算要清楚解釋
4. 引用既文件要標明來源
5. 如果用戶詢問超過權限既資訊，要禮貌咁拒絕
6. 保持自然、親切既對話風格
7. 不知道既野就話唔清楚，唔好亂講

你既知識庫包括：
- Amway 產品資訊（營養保健品、護膚品、個人護理）
- 獎金制度
- 訂單流程
- 常見問題FAQ

現在用戶既問題：${message}`;

return {
  phone,
  message,
  user_id: user?.id || null,
  systemPrompt,
  messageId: $input.item.json.messageId
};

// Extract AI response
const aiResponse = $input.item.json.choices?.[0]?.message?.content || '抱歉，請稍後再試。';

return {
  response: aiResponse,
  phone: $input.item.json.phone,
  messageId: $input.item.json.messageId
};

// Format Green API message payload
const response = $input.item.json.response;
const phone = $input.item.json.phone;

// Green API requires chatId format: 85212345678@c.us
const chatId = phone + '@c.us';

return {
  chatId,
  message: response
};

// Return success response
return {
  success: true,
  message: 'Response sent successfully'
};
